public static class TokenizerProbe
{
    public static void Probe()
    {
        string vocabPath = @"..\..\..\..\..\data\tokenizer\vocab.json";
        string mergesPath = @"..\..\..\..\..\data\tokenizer\merges.txt";

        if (!File.Exists(vocabPath))
        {
            // fallback to relative from root
            vocabPath = @"data\tokenizer\vocab.json";
            mergesPath = @"data\tokenizer\merges.txt";
        }

        Console.WriteLine($"Loading vocab from: {Path.GetFullPath(vocabPath)}");
        Console.WriteLine($"Loading merges from: {Path.GetFullPath(mergesPath)}");

        try
        {
            var tokenizer = BpeTokenizer.Create(vocabPath, mergesPath);
            Console.WriteLine("BpeTokenizer successfully created!");
            var tokens = tokenizer.Encode("The server listens on port 8000");
            Console.WriteLine($"Encoded token count: {tokens.Tokens.Count}");
            foreach (var tok in tokens.Tokens)
            {
                Console.WriteLine($"  [{tok.Id}] '{tok.Value}'");
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error: {ex.Message}\n{ex.StackTrace}");
        }
    }
}
